import type { ts, Shape, Plugin, Result } from '@servicenow/sdk-build-core'
import type { Project } from '../project'

export class Targeter {
    constructor(private readonly project: Project) {}

    async getTarget(shape: Shape, ...plugins: Plugin[]): Promise<Result<ts.Node>> {
        for (const plugin of plugins.length > 0 ? plugins : this.project.getPlugins().toArray()) {
            const result = await plugin.getTarget(shape, this.project.getContext())
            if (result.success) {
                return result
            }
        }

        return { success: false }
    }
}
